#!/usr/bin/env bash
# IEEE polish: multi-seed routing (log-x figures + AIQ±std) + NTC overhead/limitations.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing paper-polish scripts..."
decode "scripts/paper_routing.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_figures.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Run:"
echo "  # 1) routing multi-seed + polished log-x figures (~10-15 min, cached embeddings)"
echo "  python scripts/paper_routing.py --seeds 42 43 44"
echo "  # 2) regenerate NTC figures + RESULTS.md with overhead + limitations (instant)"
echo "  python scripts/ntc_w1_figures.py --probes experiments/ntc/w1_math500_Qwen3-4B.json --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json --probes experiments/ntc/w1_math500_Qwen3-1.7B.json"